const faceProfile=[[-.1225,.005,.017],[-.113,.034,.043],[-.095,.055,.060],[-.071,.069,.073],[-.045,.078,.081],[-.014,.084,.087],[.020,.082,.089],[.055,.078,.087],[.088,.066,.075],[.111,.043,.049],[.1225,.002,.004]];
