 for(let i=0;i<rows;i++)for(let j=0;j<count;j++){const a=i*(count+1)+j,b=a+1,c=a+count+1,d=c+1;indices.push(a,b,c,b,d,c);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();return g;
