function scalpGeometry(){const rows=15,count=36,p=[],uv=[],indices=[];for(let i=0;i<=rows;i++)for(let j=0;j<=count;j++){const a=j/count*Math.PI*2,front=(Math.cos(a)+1)/2,maxPhi=1.85-front*.81,phi=i/rows*maxPhi;p.push(Math.sin(phi)*Math.sin(a)*.086,Math.cos(phi)*.144,Math.sin(phi)*Math.cos(a)*.095-.009);uv.push(j/count,i/rows);}for(let i=0;i<rows;i++)for(let j=0;j<count;j++){const a=i*(count+1)+j,b=a+1,c=a+count+1,d=c+1;indices.push(a,c,b,b,c,d);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();return g;}

