  let shoulder=moving?s*stride*.72:breath*.009,elbow=-.05;if(carry||read){shoulder=-.22;elbow=-1.05;}else if(work){shoulder=-.45+Math.sin(t*7.5+i*.22)*.12;elbow=-.75+Math.cos(t*7.5+i*.22)*.19;}else if(prepare){shoulder=-.47;elbow=-.78;}else if(speaking&&i===1){shoulder=-.27+Math.sin(t*1.8)*.08;elbow=-.61;}else if(point&&i===1){shoulder=-1.1;elbow=-.12;}else if(jump>0){shoulder=-.45;elbow=-.6;}u.arms[i].rotation.x=shoulder;u.arms[i].rotation.z=side*(carry||read?-.035:.045);u.elbows[i].rotation.x=elbow;const hand=u.hands[i];hand.rotation.x=carry||read?-.18:work?-.08:0;for(let j=0;j<hand.userData.fingers.length;j++)hand.userData.fingers[j].rotation.x=carry||read?-.65:work?-.32:-.10;
