// Sculpted head and neck derived from the official MakeHuman base mesh, CC0.
// Only head surface geometry is embedded; source body and helpers are excluded.
const SCULPTED_HEAD_POSITIONS="";
const SCULPTED_HEAD_INDICES="";

export function sculptedHeadGeometry(){
 const unpack=(str,signed)=>{const bytes=Uint8Array.from(atob(str),c=>c.charCodeAt(0)),view=new DataView(bytes.buffer);return Array.from({length:bytes.length/2},(_,i)=>signed?view.getInt16(i*2,true)/100000:view.getUint16(i*2,true));};
 const positions=unpack(SCULPTED_HEAD_POSITIONS,true),indices=unpack(SCULPTED_HEAD_INDICES,false),uv=[],morph=positions.slice();
 for(let i=0;i<positions.length;i+=3){const x=positions[i],y=positions[i+1],z=positions[i+2];uv.push(.5+Math.atan2(x,z)/Math.PI/2,(y+.16)/.31);const weight=Math.max(0,1-Math.abs(x)/.085)*clamp((-.026-y)/.05,0,1)*clamp((z-.045)/.05,0,1);morph[i+1]-=.007*weight;morph[i+2]+=.002*weight;}
 // The source includes a flared neck cut. Narrow only its lower attachment
 // into the standing collar, preserving the sculpted jaw and face above it.
 for(let i=0;i<positions.length;i+=3){const y=positions[i+1],blend=clamp((-.075-y)/.07,0,1);positions[i]+=(clamp(positions[i],-.039,.039)-positions[i])*blend;positions[i+2]+=(clamp(positions[i+2],-.035,.047)-positions[i+2])*blend;morph[i]=positions[i];morph[i+2]=positions[i+2];}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.morphAttributes.position=[new T.Float32BufferAttribute(morph,3)];g.computeVertexNormals();g.computeBoundingBox();return g;
}

// Fitted covers use the sculpt itself, so no undersized sphere can expose a bald
// crown or produce disconnected dark wedges at the temples.
export function fittedHeadCover(bonnet=false){
 const source=sculptedHeadGeometry(),a=source.attributes.position,n=source.attributes.normal,positions=Float32Array.from(a.array),indices=[],offset=bonnet?.007:.0028;
 for(let i=0;i<a.count;i++){positions[i*3]+=n.getX(i)*offset;positions[i*3+1]+=n.getY(i)*offset;positions[i*3+2]+=n.getZ(i)*offset;}
 const threshold=i=>{const z=a.getZ(i),front=clamp((z+.015)/.11,0,1);return (bonnet?-.09:-.075)+front*(bonnet?.17:.137);};
 for(let i=0;i<source.index.count;i+=3){const ids=[source.index.getX(i),source.index.getX(i+1),source.index.getX(i+2)],height=ids.reduce((sum,j)=>sum+a.getY(j)-threshold(j),0)/3;if(height>=0&&ids.every(j=>a.getY(j)>threshold(j)-.017))indices.push(...ids);}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(positions,3));g.setAttribute('uv',source.attributes.uv.clone());g.setIndex(indices);g.computeVertexNormals();g.computeBoundingBox();source.dispose();return g;
}
